architecture.h4_f:
msg = CBOR{v:1, текст, жооп берүү, жөнөтүлгөн_ат}
ct = AES-GCM-256-Шифрлөө(k, nonnce, msg, aad=room_id)
POST /api/rooms/{id}/messages {шифрленген текст: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, текст, жооп_берүү?, thread_id?, эскерүүлөр?, жөнөтүлгөн_ат}
ct = AES-GCM-256-Шифрлөө(бөлмө_ачкычы, бир жолу, pt, aad=hex(бөлмө_ид))
зым = CBOR{
  v: 1,
  шифрленген текст: hex(ct), // өзгөрмө узундук
  nonce: hex(12 B),
  sender_pseudo: hex(16 B),
  жөнөтүлгөн_ат: unix_ms
}

cryptoWire.h5_f:
тышкы = CBOR{
  булак_түйүн: hex32,
  target_user: int64,
  ички_шифрленген текст: байт,
  inner_nonce: байт,
  жөнөтүлгөн_ат: unix_ms
}
sig = Ed25519-Кол (булак_priv, сырткы)
POST /federation/deliver { конверт: сырткы, сиг: hex64 }

auth.h1_f:
POST /api/аутентификация/регистр
  { колдонуучу аты, сырсөз, x25519_public_key, дисплей_аты, телефон?, электрондук почта?, avatar_emoji }

Жооп 201 Түзүлгөн:
  { access_token, refresh_token, user_id, колдонуучунун аты, ...}

auth.h4_f:
register_begin(): чакырык = rand(32)
                    опциялар = {rp.id, user.id, pubKeyCredParams, чакырык}
                    кайтаруу параметрлери

register_finish(аттестация):
  TPM / Secure Enclave root CA менен аттестацияны текшерүү
  дүкөн {credential_id, public_key, counter: 0}

auth.h7_f:
POST /api/authentication/qr/begin
  → { жок: 128-бит алтылык, ttl: 60 }
QR пайдалуу жүк = { бир жолу, колдонуучу_идентификатору, сервер: "https://node.example" }

POST /api/authentication/qr/verify { бир жолу эмес }
  → жаңы түзмөк катталган; JWTs кайтып келди.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(room_pseudo_salt, sender_id)[:16] // 32 hex
шифрленген текст = AES-GCM-Шифрлөө(бөлмө_ачкычы, бир жолу, CBOR_жүктөө, aad=бөлмө_идентификатору)

Жеңилүүчү кадр: { түрү:"m", бөлмө, билдирүү:{id, ct, nonnce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {файлдын аты, өлчөмү, chunk_size_hint}
            ← {жүктөө_идентификатору, chunk_size}
chunk PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct байт>
            ← 204
жыйынтыктоо POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {file_id, url}
TTL бүтө элек: 24 ч

files.h4_f:
четке кагуу_тизмеси = {
  "application/x-dosexec",
  "application/x-sharedlib",
  "application/x-mach-binary",
}
if magic.from_buffer(buf[:1024]) in deny_list: return 415

presence.h1_f:
кардар: биринчи баскыч басканда → жөнөтүү {type:"t", state:"start"}
         абал өзгөрбөсө, мындан ары 3 секундга жөнөтүлбөйт
         Акыркы баскыч басылгандан кийин 10 сек → жөнөтүү {type:"t", state:"stop"}
кабыл алгыч: акыркы "старттан" 10 секунд өткөндөн кийин, эч кандай "стоп" келбесе, автоматтык түрдө токтойт

calls.h1_f:
POST /api/calls/{room_id}/старт {видео, аудио} → call_id
WS берүү {тип:"c", түрү:"invite", call_id}
WS берүү {түр:"c", түрү:"сунуш", sdp}
WS берүү {тип:"c", түрү:"жооп", sdp}
WS берүү {тип:"c", түрү:"кандидат",ice} × N
POST /api/calls/{call_id}/end

federation.h2_f:
конверт = {
  булак_түйүн: hex32,
  target_user: int64,
  ички_шифрленген текст: байт,
  inner_nonce: байт,
  жөнөтүлгөн_ат: unix_ms,
}
sig = Ed25519Sign(source_priv, CBOR(конверт))
POST /federation/deliver { конверт, сиг }

stealth.h2_f:
ClientHello байттары = chrome_120_template менен {
  кокус = биздин кокустук,
  server_name = биздин хосттун аталышы (же ECH-оролгон),
  session_id = биздин сеанс id,
}
JA4 = t13d_xxxx_xxxx_xxxx (учурдагы Chrome туруктуулугуна дал келет)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {аты: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni(коомдук_ачкыч_from_HTTPS_record)
DGA: домен(t) = base32( SHA256(тукум ∥ YYYY-MM-DD) )[:16] + ".мисалы"

push.h4_f:
iOS NSE: didReceive(request) { дешифрлөө(request.content.userInfo) }
Android FCM: onMessageReceived(remoteMessage) { дешифрлөө(remoteMessage.data) }
Веб SW: self.addEventListener('push', e => дешифрлөө(e.data))

controller.h2_f:
курал = sign_tool
киргизүү = булак дарагы, keys/release.key
манифест = {
  версия: "0.1.0",
  курулган_: unix_ms,
  файлдар: [{path, sha256, size}, ...]
}
sig = Ed25519-Кол (release_priv, CBOR(манифест))
чыгаруу = INTEGRITY.sig.json = {манифест, кол койгон_: pub_hex, sig: sig_hex}

bots.h1_f:
түзүү: POST /api/bots {колдонуучунун аты, дисплей_аты, код}
          → {bot_id, token, pubkey}
иштетүү: процессте (түйүн ичиндеги корутин)
      OR тышкы (узак сурамжылоо /api/bots/{id}/updates, token-auth'd)
билдирүү: {текст, кол: Ed25519-Sign(bot_priv, canonical_msg)}

security.h4_f:
canary.txt (күн сайын):
  {дата, сиг: Ed25519-Кол (release_priv, дата)}
кардар текшерет → жок же жараксыз ⇒ компромисске шектелүүдө

өзгөчө кырдаал:
  админ POST /api/admin/revoke-all {себеп}
  түйүн берүүлөрү {тип:"n", окуя:"компромисс", себеби}
  кардарлар ачкычтарды аарчыйт, кайра жүктөөнү мажбурлайт

debugging.h2_f:
гистограммаларды баалоо (маршрутка + ыкма боюнча):
  vortex_http_requests_total{жол,ыкма,статус}
  vortex_http_request_duration_seconds_bucket{route,method,le}

websocket өлчөгүчтөр:
  vortex_ws_connections{түйүн}
  vortex_ws_fanout_queue_depth{бөлмө, колдонуучу}

жеке эсептегичтер:
  vortex_messages_sent_total{room_type}
  vortex_calls_started_total{түр}

login.h4_f:
ийгилиги боюнча: 201 + JWT конверт (реестрдеги формада)
2FA боюнча керек: 200 { "needs_2fa": чыныгы } (азырынча JWT жок)
ийгиликсиздик боюнча: 401 { "ката":"жараксыз_каттоо маалыматтары"}

apns.h1_f:
POST https://api.push.apple.com/3/device/<device_token>
Башкылар: apns-tepic: <bundle_id>, apns-push-type: alert, apns-collapse-id: бөлмө:42
Негизги: {апс: {эскертүү: {аталышы, денеси}}, маалымат: <мөөрү коюлган>}

bmp.h1_f:
mailbox_id = HKDF(recipient_pubkey, info="bmp-v1", len=32)
Депозит: POST /bmp/deposit {mailbox_id, blob ≤1MB}
Алып кетүү: GET /bmp/messages (auth'd)

controller.h1_f:
GET /v1/integrity → {статус, кол койгон_тарабынан, дал келген, дал келбеген, …}
GET /v1/health → {статус, версия, пабки, статистика}
GET /v1/entries → [{протокол, url}, …]
GET /v1/mirrors → [controller_url, …]

fcm.h1_f:
POST https://fcm.googleapis.com/v1/projects/<project>/messages:send
Авторизация: алып жүрүүчү <oauth2_token>
Негизги: {билдирүү: {токен: <түзмөк>, дайындар: {...мөөр менен жабылган...}, андроид: {collapse_key}}}

federation.h1_f:
конверт = {булак_түйүн, максаттуу_колдонуучу, inner_ct, inner_nonce, sent_at}
sig = Ed25519-Кол (булак_priv, CBOR(конверт))
POST /federation/deliver {конверт, сиг}
B текшерет: федерацияларга каршы белгилөө[source_node].pubkey

fts5.h1_f:
CREATE VIRTUAL TABLE messages_fts USING fts5(
  мазмун, -- токенизацияланган тилке
  room_id UNINDEXED,
  tokenize = 'unicode61 remove_diacritics 2'
);
суроо: SELECT rowid FROM messages_fts WHERE мазмун MATCH 'foo'

prekey.h1_f:
пакет = {
  identity_pk,
  signed_prekey_pk,
  signed_prekey_sig = Ed25519-Sign(identity_priv, signed_prekey_pk),
  бир жолу_алдын ала ачкычтар: [pk_0, pk_1, ..., pk_9]
}

vapid.h1_f:
VAPID ачкычтары: бир түйүн үчүн Ed25519 баскычтар
белги JWT: {aud: push_service_origin, экс: азыр + 12 саат, суб: mailto:ops@example}
push сурамынын аталыштары: Авторизация: vapid t=<jwt>, k=<vapid_public_key>
